package com.medtrack.inventory.service;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import com.medtrack.batch.entity.*; import com.medtrack.inventory.dto.*; import com.medtrack.inventory.entity.*; import com.medtrack.inventory.repository.InventoryBalanceRepository; import com.medtrack.medicine.entity.Medicine; import com.medtrack.shared.exception.*; import com.medtrack.user.entity.User; import com.medtrack.user.repository.UserRepository; import com.medtrack.warehouse.entity.*; import com.medtrack.warehouse.repository.WarehouseRepository; import java.time.LocalDate; import java.util.*; import org.junit.jupiter.api.Test;
class FefoAllocationEngineTest { @Test void ac02_allocatesEarliestExpiryFirst(){InventoryBalanceRepository balances=mock(InventoryBalanceRepository.class);WarehouseRepository warehouses=mock(WarehouseRepository.class);UserRepository users=mock(UserRepository.class);DoubleEntryLedgerService ledger=mock(DoubleEntryLedgerService.class);CriticalAuditService audit=mock(CriticalAuditService.class);Warehouse warehouse=new Warehouse("CW","Central",WarehouseType.CENTRAL_WAREHOUSE,"Address",null,null,null,WarehouseStatus.ACTIVE);UUID warehouseId=UUID.randomUUID();User actor=mock(User.class);when(warehouses.findById(warehouseId)).thenReturn(Optional.of(warehouse));when(users.findById(any())).thenReturn(Optional.of(actor));when(ledger.record(any(),any(),any(),any(),any(),any())).thenReturn(mock(InventoryJournalEntry.class));Medicine medicine=new Medicine("MED-ANT-00042","Drug",null,null,"TABLET","500mg","BOX",null,0,90,null);StorageLocation location=new StorageLocation(warehouse,"A","1","1","A-1-1");InventoryBalance early=balance(warehouse,location,medicine,"EARLY",LocalDate.now().plusDays(30),150);InventoryBalance late=balance(warehouse,location,medicine,"LATE",LocalDate.now().plusDays(90),150);when(balances.lockFefoCandidates(any(),eq(warehouse.getId()))).thenReturn(List.of(late,early));FefoAllocationResponse response=new FefoAllocationEngine(balances,warehouses,users,ledger,audit).allocate(UUID.randomUUID(),new FefoAllocationRequest(UUID.randomUUID(),warehouseId,200));assertEquals("EARLY",response.allocations().getFirst().batchNumber());assertEquals(150,response.allocations().getFirst().quantity());assertEquals("LATE",response.allocations().get(1).batchNumber());assertEquals(50,response.allocations().get(1).quantity());} private InventoryBalance balance(Warehouse w,StorageLocation l,Medicine m,String number,LocalDate expiry,int quantity){InventoryBalance b=new InventoryBalance(w,new Batch(number,m,new com.medtrack.supplier.entity.Supplier("S",number,null,null,null),LocalDate.now().minusDays(1),expiry,quantity,BatchStatus.ACTIVE),l);b.receive(quantity);return b;}}
